//! The Rust of org.example.warehouse.Packing, ported from Java (CodeCoreMorph, D-92): how goods
//! are packed, with how many pieces a pack holds.
use codecoremorph_java::Exception;

/// The constants keep Java's order, so an ordinal is the same in both.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Packing {
    Piece,
    Dozen,
    Crate,
}

const CONSTANTS: [(Packing, &str, i32); 3] =
    [(Packing::Piece, "pc", 1), (Packing::Dozen, "dz", 12), (Packing::Crate, "cr", 48)];

impl Packing {
    /// `Packing.values()[ordinal]`: ArrayIndexOutOfBoundsException past the constants.
    pub fn at(ordinal: i32) -> Result<Packing, Exception> {
        usize::try_from(ordinal)
            .ok()
            .and_then(|i| CONSTANTS.get(i))
            .map(|c| c.0)
            .ok_or_else(|| {
                Exception::new("java.lang.ArrayIndexOutOfBoundsException", ordinal.to_string())
            })
    }

    /// `ordinal()`.
    pub fn ordinal(self) -> i32 {
        self as i32
    }

    /// `symbol()`: "pc", "dz", "cr".
    pub fn symbol(self) -> &'static str {
        CONSTANTS[self as usize].1
    }

    /// `toPieces(int)`: the pieces in this many packs, wrapping as Java's int does.
    pub fn to_pieces(self, packs: i32) -> i32 {
        packs.wrapping_mul(CONSTANTS[self as usize].2)
    }

    /// `bySymbol(String)`: the packing with this symbol; IllegalArgumentException for none.
    pub fn by_symbol(symbol: &str) -> Result<Packing, Exception> {
        CONSTANTS
            .iter()
            .find(|c| c.1 == symbol)
            .map(|c| c.0)
            .ok_or_else(|| Exception::illegal_argument(format!("no packing {symbol}")))
    }
}

