//! The Rust of org.example.warehouse.ShelfFullException, ported from Java (CodeCoreMorph,
//! D-92): thrown when a shelf can't take a product's weight. A checked exception of the
//! project's, which the Java tests catch, so it stays a Java class: the Rust error is an
//! `Exception` of its Java type, with its constructor's arguments as fields.
use codecoremorph_java::Exception;

/// The Java type of the error.
pub const SHELF_FULL: &str = "org.example.warehouse.ShelfFullException";

/// `new ShelfFullException(shelf, overGrams)`: "shelf A2 is full: 250 g over"; a null shelf
/// name prints as "null", as Java's does, and leaves its field out.
pub fn shelf_full(shelf: Option<&str>, over_grams: i32) -> Exception {
    let mut fields = Vec::new();
    if let Some(name) = shelf {
        fields.push(("shelf".to_string(), name.to_string()));
    }
    fields.push(("overGrams".to_string(), over_grams.to_string()));
    Exception::with_fields(
        SHELF_FULL,
        format!("shelf {} is full: {over_grams} g over", shelf.unwrap_or("null")),
        fields,
    )
}

/// `e.getOverGrams()` of a shelf-full error, or None for another error.
pub fn over_grams(e: &Exception) -> Option<i32> {
    if e.java_type() != SHELF_FULL {
        return None;
    }
    e.fields().iter().find(|(name, _)| name == "overGrams").and_then(|(_, v)| v.parse().ok())
}

