//! The Rust of org.example.warehouse.Sku, ported from Java (CodeCoreMorph, D-92): a
//! stock-keeping unit, a two-letter family, a number and a check digit, as in "AB-1234-7".
//! Immutable: a value type.
use codecoremorph_java::{lang, Exception};
use std::fmt;

#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct Sku {
    family: String,
    number: i32,
}

/// `Character.isUpperCase(char)` for Basic Latin and Latin-1: A-Z, and U+00C0-U+00DE but for
/// the multiplication sign U+00D7. Java's tables also say yes for other scripts' capitals
/// (Greek, Cyrillic, Latin Extended), which this port doesn't take as a family.
fn is_upper_case(unit: u16) -> bool {
    (u16::from(b'A')..=u16::from(b'Z')).contains(&unit)
        || ((0xC0..=0xDE).contains(&unit) && unit != 0xD7)
}

/// `String.split("-")`: the input whole when nothing matches, trailing empty strings dropped.
fn split_on_dash(text: &str) -> Vec<&str> {
    let mut parts: Vec<&str> = text.split('-').collect();
    if parts.len() == 1 {
        return parts;
    }
    while parts.last().is_some_and(|p| p.is_empty()) {
        parts.pop();
    }
    parts
}

/// `Integer.parseInt(s)`: its accepted forms (a sign, then ASCII digits) and its message.
fn parse_int(s: &str) -> Result<i32, Exception> {
    let fail = || Exception::number_format(format!("For input string: \"{s}\""));
    let bytes = s.as_bytes();
    let (negative, digits) = match bytes.first() {
        None => return Err(fail()),
        Some(b'-') => (true, &bytes[1..]),
        Some(b'+') => (false, &bytes[1..]),
        Some(_) => (false, bytes),
    };
    if digits.is_empty() {
        return Err(fail());
    }
    // Accumulate negatively, as Integer.parseInt does, so MIN_VALUE parses.
    let limit = if negative { i64::from(i32::MIN) } else { -i64::from(i32::MAX) };
    let mut result = 0i64;
    for &c in digits {
        if !c.is_ascii_digit() {
            return Err(fail());
        }
        result = result * 10 - i64::from(c - b'0');
        if result < limit {
            return Err(fail());
        }
    }
    i32::try_from(if negative { result } else { -result }).map_err(|_| fail())
}

/// `String.compareTo`: the first differing UTF-16 units' difference, else the lengths'.
fn compare_strings(a: &str, b: &str) -> i32 {
    for (x, y) in a.encode_utf16().zip(b.encode_utf16()) {
        if x != y {
            return i32::from(x) - i32::from(y);
        }
    }
    lang::string_length(a) - lang::string_length(b)
}

impl Sku {
    /// IllegalArgumentException unless the family is two capital letters (UTF-16 units, as Java
    /// counts them) and the number has four digits at most. Java's NullPointerException for a
    /// null family is the bridge's: a `String` isn't null.
    pub fn new(family: impl Into<String>, number: i32) -> Result<Sku, Exception> {
        let family = family.into();
        let units: Vec<u16> = family.encode_utf16().collect();
        if units.len() != 2 || !units.iter().all(|&u| is_upper_case(u)) {
            return Err(Exception::illegal_argument(format!(
                "a family is two capital letters: {family}"
            )));
        }
        if !(0..=9999).contains(&number) {
            return Err(Exception::illegal_argument(format!(
                "a number has four digits at most: {number}"
            )));
        }
        Ok(Sku { family, number })
    }

    /// Parses "AB-1234-7", checking the check digit: IllegalArgumentException for what isn't
    /// three parts or has a wrong check digit, NumberFormatException for a part that isn't a
    /// number (Integer.parseInt's message).
    pub fn parse(text: &str) -> Result<Sku, Exception> {
        // String.trim: what is at most U+0020 at either end.
        let parts = split_on_dash(text.trim_matches(|c: char| c <= ' '));
        if parts.len() != 3 {
            return Err(Exception::illegal_argument(format!("not a SKU: {text}")));
        }
        let number = parse_int(parts[1])?;
        let sku = Sku::new(parts[0], number)?;
        if sku.check_digit() != parse_int(parts[2])? {
            return Err(Exception::illegal_argument(format!("wrong check digit: {text}")));
        }
        Ok(sku)
    }

    pub fn family(&self) -> &str {
        &self.family
    }

    pub fn number(&self) -> i32 {
        self.number
    }

    /// The sum of the family's letters (their UTF-16 units) and the number's digits, modulo 10.
    pub fn check_digit(&self) -> i32 {
        let mut sum: i32 = self.family.encode_utf16().take(2).map(i32::from).sum();
        let mut n = self.number;
        while n > 0 {
            sum += n % 10;
            n /= 10;
        }
        sum % 10
    }

    /// By family (String.compareTo, over UTF-16 units), then by number.
    pub fn compare_to(&self, other: &Sku) -> i32 {
        match compare_strings(&self.family, &other.family) {
            0 => self.number.cmp(&other.number) as i32,
            by_family => by_family,
        }
    }

    /// `hashCode()`, as Java computes it: 31 * family.hashCode() + number, wrapping.
    pub fn hash_code(&self) -> i32 {
        lang::string_hash(&self.family).wrapping_mul(31).wrapping_add(self.number)
    }
}

/// `toString()`: "AB-0007-8".
impl fmt::Display for Sku {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}-{:04}-{}", self.family, self.number, self.check_digit())
    }
}

