/// The object of a handle as the class an export of its own member needs.
fn derived<T: Product>(this: *const warehouse_Product, what: &str) -> Result<Arc<T>, Exception> {
    Arc::clone(ccm::from_handle(this)?)
        .as_any()
        .downcast::<T>()
