/// Over this many grams, a quantity ships as freight.
const FREIGHT_GRAMS: i32 = 30000;

/// What `Product` holds for its subclasses: the SKU and the name (Java's may be null).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ProductBase {
    sku: Sku,
    name: Option<String>,
}

impl ProductBase {
    /// `protected Product(Sku, String)`: Java's NullPointerException("sku") for a null SKU is the
    /// bridge's, as a `Sku` isn't null.
    pub fn new(sku: Sku, name: Option<String>) -> ProductBase {
        ProductBase { sku, name }
    }
}

/// `org.example.warehouse.Product`: something the warehouse stocks.
pub trait Product: Any + Send + Sync {
    fn base(&self) -> &ProductBase;

    /// `getSku()`.
    fn sku(&self) -> &Sku {
        &self.base().sku
    }

    /// `getName()`: None for Java's null.
    fn name(&self) -> Option<&str> {
        self.base().name.as_deref()
    }

    /// `weightGrams(int)`: what this many pieces weigh, in grams.
    fn weight_grams(&self, pieces: i32) -> i32;

    /// `isFreight(int)`: whether it ships as freight, over 30 kg for the quantity.
    fn is_freight(&self, pieces: i32) -> bool {
        self.weight_grams(pieces) > FREIGHT_GRAMS
    }

    /// `label(int)`: a shipping label, "AB-1234-7 Bolt x10 (1.5 kg)".
    fn label(&self, pieces: i32) -> String {
        let grams = self.weight_grams(pieces);
        format!(
            "{} {} x{pieces} ({}.{} kg)",
            self.sku(),
            self.name().unwrap_or("null"),
            grams / 1000,
            grams % 1000 / 100
        )
    }

    /// The object as `Any`, so the bridge can tell a Part from a Kit.
    fn as_any(self: Arc<Self>) -> Arc<dyn Any + Send + Sync>;
}

/// `org.example.warehouse.Part`: a single part, of a fixed weight per piece.
#[derive(Debug)]
