    base: ProductBase,
    grams_each: i32,
}

impl Part {
    /// IllegalArgumentException for a part that weighs nothing.
    pub fn new(sku: Sku, name: Option<String>, grams_each: i32) -> Result<Part, Exception> {
        let base = ProductBase::new(sku, name);
        if grams_each <= 0 {
            return Err(Exception::illegal_argument(format!(
                "a part weighs something: {grams_each}"
            )));
        }
        Ok(Part { base, grams_each })
    }

    /// `getGramsEach()`.
    pub fn grams_each(&self) -> i32 {
        self.grams_each
    }
}

impl Product for Part {
    fn base(&self) -> &ProductBase {
        &self.base
    }

    fn weight_grams(&self, pieces: i32) -> i32 {
        pieces.wrapping_mul(self.grams_each)
    }

    fn as_any(self: Arc<Self>) -> Arc<dyn Any + Send + Sync> {
        self
    }
}

/// `org.example.warehouse.Kit`: parts sold together, with the box they come in. Its parts are
/// behind its own lock, so a shared kit takes parts from any thread.
#[derive(Debug)]
pub struct Kit {
    base: ProductBase,
    parts: Mutex<Vec<Arc<Part>>>,
    box_grams: i32,
}

impl Kit {
    pub fn new(sku: Sku, name: Option<String>, box_grams: i32) -> Kit {
        Kit { base: ProductBase::new(sku, name), parts: Mutex::new(Vec::new()), box_grams }
    }

    fn locked(&self) -> MutexGuard<'_, Vec<Arc<Part>>> {
        self.parts.lock().unwrap_or_else(PoisonError::into_inner)
    }

    /// `with(Part)`: adds a part; a kit holds no part twice (IllegalStateException).
    pub fn with(&self, part: Arc<Part>) -> Result<&Kit, Exception> {
        let mut parts = self.locked();
        if parts.iter().any(|p| p.sku() == part.sku()) {
            return Err(Exception::illegal_state(format!("already in the kit: {}", part.sku())));
        }
        parts.push(part);
        Ok(self)
    }

    /// `getParts()`: the parts, in the order they were added (a copy of the list).
    pub fn parts(&self) -> Vec<Arc<Part>> {
        self.locked().clone()
    }
}

impl Product for Kit {
    fn base(&self) -> &ProductBase {
        &self.base
    }

    fn weight_grams(&self, pieces: i32) -> i32 {
        let each =
            self.locked().iter().fold(self.box_grams, |each, p| each.wrapping_add(p.weight_grams(1)));
        pieces.wrapping_mul(each)
    }

    /// A kit of more than ten parts always ships as freight.
    fn is_freight(&self, pieces: i32) -> bool {
        // The lock goes before weight_grams takes it again.
        let many = self.locked().len() > 10;
        many || self.weight_grams(pieces) > FREIGHT_GRAMS
    }

    fn as_any(self: Arc<Self>) -> Arc<dyn Any + Send + Sync> {
        self
    }
}

