import codecoremorph.interop.CcmInterop;
import codecoremorph.interop.CcmNative;

/**
 * A shelf of one kind of product, up to a load in grams.
 */
public class Shelf<T extends Product> {
    private final long handle;

    public Shelf(String name, int loadGrams) {
        long[] result = new long[1];
        CcmInterop.check(CcmNative.warehouse_Shelf_new(name, loadGrams, result));
        handle = CcmInterop.track(this, result[0], CcmNative::warehouse_Shelf_release);
    }

    public String getName() {
        String[] result = new String[1];
        CcmInterop.check(CcmNative.warehouse_Shelf_getName(handle, result));
        return result[0];
    }

    /** Puts this many pieces of a product on the shelf, if it holds their weight. */
    public void put(T product, int count) throws ShelfFullException {
        CcmInterop.check(CcmNative.warehouse_Shelf_put(handle, Product.handleOf(product), count));
    }

    public int weightGrams() {
        int[] result = new int[1];
        CcmInterop.check(CcmNative.warehouse_Shelf_weightGrams(handle, result));
        return result[0];
    }

    public int size() {
        int[] result = new int[1];
        CcmInterop.check(CcmNative.warehouse_Shelf_size(handle, result));
        return result[0];
    }

    /** The product at a position; IndexOutOfBoundsException past the end. */
    public T get(int index) {
        long[] result = new long[1];
        CcmInterop.check(CcmNative.warehouse_Shelf_get(handle, index, result));
        // What put() was given is a T: the object that comes back is the same one.
        return (T) Product.fromHandle(result[0]);
    }
}

//! The bridge of org.example.warehouse.StockListener: a trait Java classes implement (the tests'
//! anonymous listeners), reaching the Rust through a proxy over a function pointer per member.
use super::ccm::{self, ccm_release_fn, ccm_status, Handle, ManagedRef};
use crate::sku::Sku;
use crate::stock_listener::StockListener;
use codecoremorph_java::Exception;
use std::ffi::{c_char, c_void, CString};
use std::ptr;
use std::sync::Arc;

pub struct warehouse_StockListener {
    _private: [u8; 0],
}

impl Handle for warehouse_StockListener {
    type Target = dyn StockListener;
}

#[unsafe(no_mangle)]
pub extern "C" fn warehouse_StockListener_release(handle: *mut warehouse_StockListener) {
    ccm::release(handle)
}

#[unsafe(no_mangle)]
pub extern "C" fn warehouse_StockListener_key(handle: *const warehouse_StockListener) -> u64 {
    ccm::key(handle)
}

/// StockListener.changed (the SKU as its fields; a null family for a null SKU).
pub type warehouse_StockListener_changed_fn = Option<
    unsafe extern "C" fn(
        context: *mut c_void,
        sku_family: *const c_char,
        sku_number: i32,
        before: i32,
        after: i32,
    ) -> ccm_status,
>;

/// A SKU as C fields for a call into Java: a null family for a null SKU.
pub(super) struct SkuFields {
    family: Option<CString>,
    number: i32,
}

impl SkuFields {
    pub(super) fn of(sku: Option<&Sku>) -> Result<SkuFields, Exception> {
        let family = sku
            .map(|s| CString::new(s.family()))
            .transpose()
            .map_err(|_| Exception::illegal_argument("a family with a NUL"))?;
        Ok(SkuFields { family, number: sku.map_or(0, Sku::number) })
    }

    pub(super) fn family(&self) -> *const c_char {
        self.family.as_ref().map_or(ptr::null(), |f| f.as_ptr())
    }

    pub(super) fn number(&self) -> i32 {
        self.number
    }
}

/// A Java StockListener, called through the function pointer the Java façade passed. A Java
/// exception thrown there comes back as `Exception::managed()`, and the façade rethrows it.
struct ManagedStockListener {
    managed: Arc<ManagedRef>,
    changed: unsafe extern "C" fn(*mut c_void, *const c_char, i32, i32, i32) -> ccm_status,
}

impl StockListener for ManagedStockListener {
    fn changed(&self, sku: Option<&Sku>, before: i32, after: i32) -> Result<(), Exception> {
        let fields = SkuFields::of(sku)?;
        // SAFETY: the glue's trampoline, called with the context it was given and C fields that
        // live for the call.
        let status = unsafe {
            (self.changed)(self.managed.context(), fields.family(), fields.number(), before, after)
        };
        ccm::check_managed(status)
    }
}

/// A Rust StockListener over a Java one: it keeps the context until its last owner lets go.
#[unsafe(no_mangle)]
pub extern "C" fn warehouse_StockListener_from_managed(
    context: *mut c_void,
    release: ccm_release_fn,
    changed: warehouse_StockListener_changed_fn,
    result: *mut *mut warehouse_StockListener,
) -> ccm_status {
    let managed = ManagedRef::new(context, release);
    ccm::guard(|| {
        let changed = ccm::callback(changed)?;
        let listener: Arc<dyn StockListener> = Arc::new(ManagedStockListener { managed, changed });
        ccm::put(result, ccm::to_handle::<warehouse_StockListener>(listener));
        Ok(())
    })
}

//! The Rust of org.example.warehouse.StockListener, ported from Java (CodeCoreMorph, D-92):
//! told of each change to a stock's count of a SKU.
use crate::sku::Sku;
use codecoremorph_java::Exception;

pub trait StockListener: Send + Sync {
    /// `changed(Sku, int, int)`. The SKU may be None, as a Java stock's may hold a null one; an
    /// error (a Java listener's exception) stops the stock's report of the change.
    fn changed(&self, sku: Option<&Sku>, before: i32, after: i32) -> Result<(), Exception>;
}

