package org.example.warehouse;

import codecoremorph.interop.CcmInterop;
import codecoremorph.interop.CcmNative;

/**
 * Told of each change to a stock's count of a SKU.
 */
public interface StockListener {
    void changed(Sku sku, int before, int after);
}

// The native handle of any StockListener: a proxy over a Java one (no ported class implements
// it).
final class StockListeners {
    private StockListeners() {
    }

    /** A new handle the caller releases (warehouse_StockListener_release); 0 for null. */
    static long handleOf(StockListener listener) {
        if (listener == null) {
            return 0;
        }
        long[] result = new long[1];
        CcmInterop.check(CcmNative.warehouse_StockListener_from_managed(new Proxy(listener),
            result));
        return result[0];
    }

    private static final class Proxy implements CcmNative.warehouse_StockListener_changed_fn {
        private final StockListener listener;

        Proxy(StockListener listener) {
            this.listener = listener;
        }

        @Override
        public int call(String skuFamily, int skuNumber, int before, int after) {
            listener.changed(Sku.of(skuFamily, skuNumber), before, after);
            return CcmInterop.OK;
        }
    }
}

