        context: *mut c_void,
        sku_family: *const c_char,
        sku_number: i32,
        result: *mut bool,
    ) -> ccm_status,
>;

/// A Sku the Java may pass as null (a null family): None for null.
fn opt_sku(family: *const c_char, number: i32) -> Result<Option<Sku>, Exception> {
    ccm::opt_str(family).map(|f| Sku::new(f, number)).transpose()
}

fn packing_of(ordinal: i32) -> Result<Option<Packing>, Exception> {
    if ordinal < 0 {
        return Ok(None);
    }
    Packing::at(ordinal).map(Some)
}

#[unsafe(no_mangle)]
pub extern "C" fn warehouse_Stock_new(result: *mut *mut warehouse_Stock) -> ccm_status {
