    this: *mut warehouse_Stock,
    sku_family: *const c_char,
    sku_number: i32,
    packing: i32,
    packs: i32,
) -> ccm_status {
    ccm::guard(|| {
        let sku = opt_sku(sku_family, sku_number)?;
        ccm::from_handle(this)?.receive(sku.as_ref(), packing_of(packing)?, packs)
    })
