#[unsafe(no_mangle)]
pub extern "C" fn warehouse_Stock_take(
    this: *mut warehouse_Stock,
    sku_family: *const c_char,
    sku_number: i32,
    pieces: i32,
) -> ccm_status {
    ccm::guard(|| {
        let sku = opt_sku(sku_family, sku_number)?;
        ccm::from_handle(this)?.take(sku.as_ref(), pieces)
    })
}

#[unsafe(no_mangle)]
pub extern "C" fn warehouse_Stock_count(
    this: *const warehouse_Stock,
    sku_family: *const c_char,
    sku_number: i32,
    result: *mut i32,
) -> ccm_status {
    ccm::guard(|| {
        let sku = opt_sku(sku_family, sku_number)?;
        ccm::put(result, ccm::from_handle(this)?.count(sku.as_ref()));
        Ok(())
    })
}

/// The filter is only called during the call: no release. A null context is a null filter.
#[unsafe(no_mangle)]
pub extern "C" fn warehouse_Stock_total(
    this: *const warehouse_Stock,
    context: *mut c_void,
    accepts: warehouse_Stock_SkuFilter_accepts_fn,
    result: *mut i32,
) -> ccm_status {
    ccm::guard(|| {
        let stock = ccm::from_handle(this)?;
        let total = if context.is_null() {
            stock.total(None)?
        } else {
            let accepts = ccm::callback(accepts)?;
            let mut filter = |sku: Option<&Sku>| -> Result<bool, Exception> {
                let fields = SkuFields::of(sku)?;
                let mut accepted = false;
                // SAFETY: the glue's trampoline, called during the export with its context and
                // C fields that live for the call.
                let status =
                    unsafe { accepts(context, fields.family(), fields.number(), &mut accepted) };
                ccm::check_managed(status)?;
