pub extern "C" fn warehouse_Stock_report(this: *const warehouse_Stock, result: *mut *mut c_char) -> ccm_status {
    ccm::guard(|| {
        ccm::out_str(result, &ccm::from_handle(this)?.report());
        Ok(())
    })
}

//! The Rust of org.example.warehouse.Stock, ported from Java (CodeCoreMorph, D-92): counts of the
//! warehouse's SKUs, in the order they were first stocked, and the listeners told of each
//! change. Safe to share between threads: its state is behind its own lock, which it never
//! holds while it calls a listener or a filter (either may be Java, which may call back in). As
//! Java's LinkedHashMap does, it takes a null SKU (None) as a key of its own.
use crate::packing::Packing;
use crate::sku::Sku;
use crate::stock_listener::StockListener;
use codecoremorph_java::Exception;
use std::collections::HashMap;
use std::sync::{Arc, Mutex, MutexGuard, PoisonError};

/// `Stock.SkuFilter`: accepts or rejects a SKU; an error (a Java filter's exception) ends the
/// count.
pub type SkuFilter<'a> = dyn FnMut(Option<&Sku>) -> Result<bool, Exception> + 'a;

#[derive(Default)]
struct State {
    counts: Vec<(Option<Sku>, i32)>, // in first-stocked order
    positions: HashMap<Option<Sku>, usize>,
    // A null listener is kept, as Java's list keeps it, and fails the next change report.
    listeners: Vec<Option<Arc<dyn StockListener>>>,
}

impl State {
    fn count(&self, sku: Option<&Sku>) -> Option<i32> {
        self.positions.get(&sku.cloned()).map(|&at| self.counts[at].1)
    }
}

#[derive(Default)]
pub struct Stock {
    state: Mutex<State>,
}

fn shown(sku: Option<&Sku>) -> String {
    sku.map_or_else(|| "null".to_string(), Sku::to_string)
}

impl Stock {
    pub fn new() -> Stock {
        Stock::default()
    }

    fn locked(&self) -> MutexGuard<'_, State> {
        self.state.lock().unwrap_or_else(PoisonError::into_inner)
    }

    /// `addListener(StockListener)`.
    pub fn add_listener(&self, listener: Option<Arc<dyn StockListener>>) {
        self.locked().listeners.push(listener);
    }

    /// `receive(Sku, Packing, int)`: IllegalArgumentException for no pack, then
    /// NullPointerException for no packing.
    pub fn receive(&self, sku: Option<&Sku>, packing: Option<Packing>, packs: i32) -> Result<(), Exception> {
        if packs <= 0 {
            return Err(Exception::illegal_argument(format!("receive at least one pack: {packs}")));
        }
        let packing = packing.ok_or_else(|| Exception::null_pointer(None))?;
        self.change(sku, packing.to_pieces(packs))
    }

    /// `take(Sku, int)`: NoSuchElementException for a SKU never stocked, IllegalStateException
    /// for more than it has.
    pub fn take(&self, sku: Option<&Sku>, pieces: i32) -> Result<(), Exception> {
        let have = self
            .locked()
            .count(sku)
            .ok_or_else(|| Exception::no_such_element(format!("never stocked: {}", shown(sku))))?;
        if pieces > have {
            return Err(Exception::illegal_state(format!(
                "only {have} of {} in stock",
                shown(sku)
            )));
        }
        self.change(sku, pieces.wrapping_neg())
    }

    /// `count(Sku)`.
    pub fn count(&self, sku: Option<&Sku>) -> i32 {
        self.locked().count(sku).unwrap_or(0)
    }

    /// `total(SkuFilter)`: how many pieces of the SKUs the filter accepts are in stock; None is
    /// Java's null filter (NullPointerException once there is a SKU to ask it of). The filter
    /// runs on the counts as they were when the call began, outside the lock.
    pub fn total(&self, mut filter: Option<&mut SkuFilter<'_>>) -> Result<i32, Exception> {
        let counts = self.locked().counts.clone();
        let mut total = 0i32;
        for (sku, count) in &counts {
            let Some(accepts) = filter.as_deref_mut() else {
                return Err(Exception::null_pointer(None));
            };
            if accepts(sku.as_ref())? {
                total = total.wrapping_add(*count);
            }
        }
        Ok(total)
    }

    /// `report()`: one line per SKU, in the order they were first stocked: "AB-1234-7: 12".
    pub fn report(&self) -> String {
        self.locked()
            .counts
            .iter()
            .map(|(sku, count)| format!("{}: {count}\n", shown(sku.as_ref())))
            .collect()
    }

    fn change(&self, sku: Option<&Sku>, delta: i32) -> Result<(), Exception> {
        let (before, after, told) = {
            let mut state = self.locked();
            let key = sku.cloned();
            let (before, after) = match state.positions.get(&key).copied() {
                Some(at) => {
                    let before = state.counts[at].1;
                    let after = before.wrapping_add(delta);
                    state.counts[at].1 = after;
                    (before, after)
                }
                None => {
                    let at = state.counts.len();
                    state.counts.push((key.clone(), delta));
                    state.positions.insert(key, at);
                    (0, delta)
                }
            };
            (before, after, state.listeners.clone())
        };
        for listener in told {
            listener.ok_or_else(|| Exception::null_pointer(None))?.changed(sku, before, after)?;
        }
        Ok(())
    }
}

