//! The tests of src/test/java/org/example/warehouse/PackingTest.java, translated from Java (CodeCoreMorph, D-92): a `#[test]` per
//! Java test case, each mapped in rust/test-map.toml. Java's Parameterized cases are a test
//! each, named by the symbol Java's runner named them by.
use warehouse_rs::packing::Packing;

/// `countsPieces`: a symbol, a number of packs, and the pieces they hold.
fn counts_pieces(symbol: &str, packs: i32, pieces: i32) {
    let packing = Packing::by_symbol(symbol).unwrap();
    assert_eq!(pieces, packing.to_pieces(packs));
    // assertSame(packing, Packing.valueOf(packing.name())): the constant comes back from its
    // ordinal, Rust's way to name it.
    assert_eq!(packing, Packing::at(packing.ordinal()).unwrap());
    assert_eq!(symbol, packing.symbol());
}

#[test]
fn counts_pieces_pc() {
    counts_pieces("pc", 3, 3);
}

#[test]
fn counts_pieces_dz() {
    counts_pieces("dz", 2, 24);
}

#[test]
fn counts_pieces_cr() {
    counts_pieces("cr", 1, 48);
}

