use warehouse_rs::product::{Kit, Part, Product};
use warehouse_rs::sku::Sku;

fn sku(family: &str, number: i32) -> Sku {
    Sku::new(family, number).unwrap()
}

fn part(family: &str, number: i32, name: &str, grams_each: i32) -> Arc<Part> {
    Arc::new(Part::new(sku(family, number), Some(name.to_string()), grams_each).unwrap())
}

fn kit(number: i32, name: &str, box_grams: i32) -> Kit {
    Kit::new(sku("KI", number), Some(name.to_string()), box_grams)
}

fn bolt() -> Arc<Part> {
    part("BO", 10, "Bolt", 150)
}

fn nut() -> Arc<Part> {
    part("NU", 10, "Nut", 40)
}

#[test]
fn a_part_weighs_its_pieces() {
    let bolt = bolt();
    assert_eq!(1500, bolt.weight_grams(10));
    assert_eq!("BO-0010-6 Bolt x10 (1.5 kg)", bolt.label(10));
    assert!(!bolt.is_freight(10));
