}

#[test]
fn a_kit_holds_no_part_twice() {
    let kit = kit(4, "Kit", 10);
    kit.with(bolt()).unwrap();
    match kit.with(part("BO", 10, "Another bolt", 1)) {
        Ok(_) => panic!("no exception"),
        Err(e) => {
            assert_eq!("java.lang.IllegalStateException", e.java_type());
            assert_eq!(Some("already in the kit: BO-0010-6"), e.message());
        }
    }
}

#[test]
fn a_kits_parts_cant_be_changed() {
    // Java's getParts() is unmodifiable (add throws UnsupportedOperationException); the Rust
    // hands out a copy, so a change to it leaves the kit as it was.
    let kit = kit(5, "Kit", 10);
    let mut parts = kit.parts();
    parts.push(bolt());
    assert!(kit.parts().is_empty());
}

