//! The tests of src/test/java/org/example/warehouse/StockTest.java, translated from Java (CodeCoreMorph, D-92): a `#[test]` per
//! Java test case, each mapped in rust/test-map.toml. The Java test's anonymous listeners are
//! Rust types here.
use codecoremorph_java::Exception;
use std::sync::{Arc, Mutex};
use warehouse_rs::packing::Packing;
use warehouse_rs::sku::Sku;
use warehouse_rs::stock::Stock;
use warehouse_rs::stock_listener::StockListener;

fn of(family: &str, number: i32) -> Sku {
    Sku::new(family, number).unwrap()
}

/// The test's `setUp`: 2 dozen bolts and a crate of nuts.
fn stocked() -> (Stock, Sku, Sku) {
    let bolts = of("BO", 10);
    let nuts = of("NU", 10);
    let stock = Stock::new();
    stock.receive(Some(&bolts), Some(Packing::Dozen), 2).unwrap();
    stock.receive(Some(&nuts), Some(Packing::Crate), 1).unwrap();
    (stock, bolts, nuts)
}

/// The first anonymous listener: it records what it hears.
#[derive(Default)]
struct Recording {
    heard: Mutex<Vec<String>>,
}

impl StockListener for Recording {
    fn changed(&self, sku: Option<&Sku>, before: i32, after: i32) -> Result<(), Exception> {
        let shown = sku.map_or_else(|| "null".to_string(), Sku::to_string);
        self.heard.lock().unwrap().push(format!("{shown} {before}->{after}"));
        Ok(())
    }
}

/// The second: it throws.
struct Throwing;

fn broke() -> Exception {
    Exception::new("java.lang.RuntimeException", "listener broke")
}

impl StockListener for Throwing {
    fn changed(&self, _sku: Option<&Sku>, _before: i32, _after: i32) -> Result<(), Exception> {
        Err(broke())
    }
}

#[test]
fn counts_what_it_receives() {
    let (stock, bolts, nuts) = stocked();
    assert_eq!(24, stock.count(Some(&bolts)));
    assert_eq!(48, stock.count(Some(&nuts)));
    assert_eq!(0, stock.count(Some(&of("XX", 1))));
}

#[test]
fn takes_what_it_has() {
    let (stock, bolts, _) = stocked();
    stock.take(Some(&bolts), 20).unwrap();
    assert_eq!(4, stock.count(Some(&bolts)));
}

#[test]
fn refuses_to_take_more_than_it_has() {
    let (stock, bolts, _) = stocked();
    match stock.take(Some(&bolts), 25) {
        Ok(()) => panic!("no exception"),
        Err(e) => {
            assert_eq!("java.lang.IllegalStateException", e.java_type());
            assert_eq!(Some("only 24 of BO-0010-6 in stock"), e.message());
        }
    }
}

#[test]
fn refuses_to_take_what_it_never_had() {
    let (stock, _, _) = stocked();
    let e = stock.take(Some(&of("XX", 1)), 1).unwrap_err();
    assert_eq!("java.util.NoSuchElementException", e.java_type());
}

#[test]
fn receives_at_least_one_pack() {
    let (stock, bolts, _) = stocked();
    let e = stock.receive(Some(&bolts), Some(Packing::Piece), 0).unwrap_err();
    assert_eq!("java.lang.IllegalArgumentException", e.java_type());
}

#[test]
fn tells_its_listeners() {
    let (stock, bolts, nuts) = stocked();
    let listener = Arc::new(Recording::default());
    stock.add_listener(Some(Arc::clone(&listener) as Arc<dyn StockListener>));
    stock.take(Some(&nuts), 8).unwrap();
    stock.receive(Some(&bolts), Some(Packing::Piece), 1).unwrap();
    let heard = listener.heard.lock().unwrap();
    assert_eq!(2, heard.len());
    assert_eq!("NU-0010-4 48->40", heard[0]);
    assert_eq!("BO-0010-6 24->25", heard[1]);
}

#[test]
fn a_listener_that_throws_stops_the_change_report() {
    let (stock, _, nuts) = stocked();
    stock.add_listener(Some(Arc::new(Throwing) as Arc<dyn StockListener>));
    match stock.take(Some(&nuts), 1) {
        Ok(()) => panic!("no exception"),
        // assertSame: the listener's own error, as it was.
        Err(e) => assert_eq!(broke(), e),
    }
    assert_eq!(47, stock.count(Some(&nuts)));
}

#[test]
fn totals_what_a_filter_accepts() {
    let (stock, _, _) = stocked();
    let mut every = |_: Option<&Sku>| -> Result<bool, Exception> { Ok(true) };
    assert_eq!(72, stock.total(Some(&mut every)).unwrap());
    let mut bolts = |sku: Option<&Sku>| -> Result<bool, Exception> {
        Ok(sku.map(Sku::family) == Some("BO"))
    };
    assert_eq!(24, stock.total(Some(&mut bolts)).unwrap());
}

#[test]
fn reports_in_the_order_it_stocked() {
    let (stock, _, _) = stocked();
    stock.receive(Some(&of("AA", 1)), Some(Packing::Piece), 5).unwrap();
    assert_eq!("BO-0010-6: 24\nNU-0010-4: 48\nAA-0001-1: 5\n", stock.report());
}
